import{_ as n,a0 as r,w as s,s as u,ao as p,I as a,x as i,a1 as o,A as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse(`{"title":"10个关于linux中Squid代理服务器的实用面试问答 | LCTT x X-CMD","titleTemplate":false,"description":"10个关于linux中Squid代理服务器的实用面试问答 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10个关于linux中Squid代理服务器的实用面试问答 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10个关于linux中Squid代理服务器的实用面试问答 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140729 10 Useful 'Squid Proxy Server' Interview Questions and Answers in Linux","title":"10个关于linux中Squid代理服务器的实用面试问答","tag":"201409","desc":""},"relativePath":"201409/20140729 10 Useful 'Squid Proxy Server' Interview Questions and Answers in Linux.md","filePath":"[post].md"}`),l={name:"201409/20140729 10 Useful 'Squid Proxy Server' Interview Questions and Answers in Linux.md"};function q(c,e,S,b,h,m){const t=r("Link");return s(),u("div",null,[e[13]||(e[13]=p(`<h1 id="_10个关于linux中squid代理服务器的实用面试问答" tabindex="-1">10个关于linux中Squid代理服务器的实用面试问答 <a class="header-anchor" href="#_10个关于linux中squid代理服务器的实用面试问答" aria-label="Permalink to “10个关于linux中Squid代理服务器的实用面试问答”">​</a></h1><p>不仅是系统管理员和网络管理员时不时会听到“代理服务器”这个词，我们也经常听到。代理服务器已经成为一种企业常态，而且经常会接触到它。它现在也出现在一些小型的学校或者大型跨国公司的自助餐厅里。Squid（常被视作代理服务的代名词）就是这样一个应用程序，它不但可以被作为代理服务器，其同时也是在该类工具中比较被广泛使用的一种。</p><p>本文旨在提高你在遇到关于代理服务器面试点时的一些基本应对能力。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Squid-Interview-Questions.png" alt="Squid Interview Questions"></p><p>以下为面试问答的内容</p><h3 id="_1-什么是代理服务器-代理服务器在计算机网络中有什么用途" tabindex="-1">1. 什么是代理服务器？代理服务器在计算机网络中有什么用途？ <a class="header-anchor" href="#_1-什么是代理服务器-代理服务器在计算机网络中有什么用途" aria-label="Permalink to “1. 什么是代理服务器？代理服务器在计算机网络中有什么用途？”">​</a></h3><blockquote><p><strong>回答</strong> : 代理服务器是指那些作为客户端和资源提供商或服务器之间的中间件的物理机或者应用程序。客户端从代理服务器中寻找文件、页面或者是数据，而且代理服务器能处理客户端与服务器之间所有复杂事务，从而满足客户端的生成的需求。</p></blockquote><p>代理服务器是WWW（万维网）的支柱，它们其中大部分都是Web代理。一台代理服务器能处理客户端与服务器之间的复杂通信事务。此外，它在网络上提供的是匿名信息（LCTT 译注：指浏览者的 IP、浏览器信息等被隐藏），这就意味着你的身份和浏览痕迹都是安全的。代理可以去配置允许哪些网站的客户能看到，哪些网站被屏蔽了。</p><h3 id="_2-squid是什么" tabindex="-1">2. Squid是什么? <a class="header-anchor" href="#_2-squid是什么" aria-label="Permalink to “2. Squid是什么?”">​</a></h3><blockquote><p><strong>回答</strong> : Squid是一个在GNU/GPL协议下发布的既可作为代理服务器，同时也可作为Web缓存守护进程的应用软件。Squid主要是支持像HTTP和FTP那样的协议，但是对其它的协议比如HTTPS，SSL,TLS等同样也能支持。其特点是Web缓存守护进程通过从经常上访问的网站里缓存Web和DNS数据，从而让上网速度更快。Squid支持所有的主流平台，包括Linux，UNIX，微软公司的Windows和苹果公司的Mac。</p></blockquote><h3 id="_3-squid的默认端口是什么-怎么去修改它的操作端口" tabindex="-1">3. Squid的默认端口是什么？怎么去修改它的操作端口？ <a class="header-anchor" href="#_3-squid的默认端口是什么-怎么去修改它的操作端口" aria-label="Permalink to “3. Squid的默认端口是什么？怎么去修改它的操作端口？”">​</a></h3><blockquote><p><strong>回答</strong> : Squid运行时的默认端口是3128。我们可以通过编辑它的配置文件来把它的默认端口修改成未被用户使用的端口，路径是 /etc/squid/squid.conf ，建议如下。</p></blockquote><p>用你的编辑器打开 ‘/etc/squid/squid.conf’ 文件。</p><pre><code># nano /etc/squid/squid.conf
</code></pre><p>现在把它修改成未被使用的其它端口，并保存退出。</p><pre><code>http_port 3128
</code></pre><p>重新启动Squid代理服务，如下显示。</p><pre><code># service squid restart
</code></pre><h3 id="_4-你的公司管理层要求你通过squid代理服务器屏蔽掉一些域名-你怎么做" tabindex="-1">4. 你的公司管理层要求你通过Squid代理服务器屏蔽掉一些域名，你怎么做？ <a class="header-anchor" href="#_4-你的公司管理层要求你通过squid代理服务器屏蔽掉一些域名-你怎么做" aria-label="Permalink to “4. 你的公司管理层要求你通过Squid代理服务器屏蔽掉一些域名，你怎么做？”">​</a></h3><blockquote><p><strong>回答</strong> : 屏蔽域名是一个在配置文件中实现的功能模块。我们只需要执行一个小的手动配置即可，建议如下。</p></blockquote><p>a. 在 ‘/etc/squid’ 目录下创建一个名为 ‘blacklist’ 的文件。</p><pre><code># touch /etc/squid/blacklist
</code></pre><p>b. 用nano编辑器打开这个文件。</p><pre><code> # nano /etc/squid/blacklist
</code></pre><p>c. 以每行一个域名的方式将想要屏蔽的域名写进这个文件里。</p><pre><code>.facebook.com
.twitter.com
.gmail.com
.yahoo.com
...
</code></pre><p>d. 保存退出，然后从 ‘/etc/squid/squid.conf’ 打开Squid配置文件。</p><pre><code># nano /etc/squid/squid.conf
</code></pre><p>e. 在配置文件中添加如下行。</p><pre><code>acl BLACKLIST dstdom_regex -i “/etc/squid/blacklist”
http_access deny blacklist
</code></pre><p>f. 保存配置文件并退出，重启Squid服务让其生效。</p><pre><code># service squid restart
</code></pre><h3 id="_5-在squid中什么是媒体范围限制-media-range-limitation-和部分下载" tabindex="-1">5. 在Squid中什么是媒体范围限制（Media Range Limitation）和部分下载？ <a class="header-anchor" href="#_5-在squid中什么是媒体范围限制-media-range-limitation-和部分下载" aria-label="Permalink to “5. 在Squid中什么是媒体范围限制（Media Range Limitation）和部分下载？”">​</a></h3><blockquote><p><strong>回答</strong> : 媒体范围限制是Squid的一种特殊的功能，它只从服务器中获取所需要的数据而不是整个文件。这个功能很好的实现了用户在各种视频流媒体网站如YouTube和Metacafe看视频时，可以点击视频中的进度条来选择进度，因此整个视频不用全部都加载，除了一些需要的部分。</p></blockquote><p>Squid部分下载功能的特点是很好地实现了类似在Windows更新时能以一个个小数据包的形式下载，并可以暂停，正因为它的这个特点，正在下载文件的Windows机器可以重新继续下载，而不用担心数据会丢失。Squid的媒体范围限制和部分下载功能只有在存储了一个完整文件的副本之后才行。此外，当用户访问另一个页面时，除非Squid进行了特定的配置，部分下载下来的文件会被删除且不留在缓存中。</p><h3 id="_6-什么是squid的反向代理" tabindex="-1">6. 什么是Squid的反向代理？ <a class="header-anchor" href="#_6-什么是squid的反向代理" aria-label="Permalink to “6. 什么是Squid的反向代理？”">​</a></h3><blockquote><p><strong>回答</strong> : 反向代理是Squid的一个功能，这个功能被用来加快最终用户的上网速度。下面用缩写 ‘RS’ 的表示包含了资源的原服务器，而代理服务器则称作 ‘PS’ 。初次访问时，它会从RS得到其提供的数据，并将其副本按照配置好的时间存储在PS上。这样的话每次从PS上请求的数据就相当于就是从原服务器上获取的。这样就会减轻网络拥堵，减少CPU使用率，降低网络资源的利用率，从而缓解原来实际服务器的负载压力。但是RS统计不了总流量的数据，因为PS分担了部分原服务器的任务。‘X-Forwarded-For HTTP’ 信息能用于记录下通过HTTP代理或负载均衡方式连接到RS的客户端最原始的IP地址。</p></blockquote><p>从技术上说，用单个Squid服务器同时作为正向代理服务器和反向代理服务器是可行的。</p><h3 id="_7-由于squid能作为一个web缓存守护进程-那缓存可以删除吗-怎么删除" tabindex="-1">7. 由于Squid能作为一个Web缓存守护进程，那缓存可以删除吗？怎么删除？ <a class="header-anchor" href="#_7-由于squid能作为一个web缓存守护进程-那缓存可以删除吗-怎么删除" aria-label="Permalink to “7. 由于Squid能作为一个Web缓存守护进程，那缓存可以删除吗？怎么删除？”">​</a></h3><blockquote><p><strong>回答</strong> : 当然！作为一个Web缓存守护进程，Squid能加快网页的访问速度，清除缓存也是非常简单的。</p></blockquote><p>a. 首先停止Squid代理服务，然后从这个 ‘/var/lib/squid/cache’ 目录中删除缓存。</p><pre><code># service squid stop
# rm -rf /var/lib/squid/cache/*&lt;
</code></pre><p>b. 创建交换分区目录。</p><pre><code># squid -z
</code></pre><h3 id="_8-你有一台工作中的机器可以访问代理服务器-如果想要限制你的孩子的访问时间-你会怎么去设置那个场景" tabindex="-1">8. 你有一台工作中的机器可以访问代理服务器，如果想要限制你的孩子的访问时间，你会怎么去设置那个场景？ <a class="header-anchor" href="#_8-你有一台工作中的机器可以访问代理服务器-如果想要限制你的孩子的访问时间-你会怎么去设置那个场景" aria-label="Permalink to “8. 你有一台工作中的机器可以访问代理服务器，如果想要限制你的孩子的访问时间，你会怎么去设置那个场景？”">​</a></h3><p>把允许访问的时间设置成晚上4点到7点三个小时，跨度为星期一到星期五。</p><p>a. 想要限制Web访问时间在星期一到星期五的晚上4点到7点，要先打开Squid的配置文件。</p><pre><code># nano /etc/squid/squid.conf
</code></pre><p>b. 在配置文件中添加如下行，保存文件并退出。</p><pre><code>acl ALLOW_TIME time M T W H F 16:00-19:00
shttp_access allow ALLOW_TIME
</code></pre><p>c. 重启Squid服务。</p><pre><code># service squid restart
</code></pre><h3 id="_9-squid存储的数据是什么文件格式" tabindex="-1">9. Squid存储的数据是什么文件格式？ <a class="header-anchor" href="#_9-squid存储的数据是什么文件格式" aria-label="Permalink to “9. Squid存储的数据是什么文件格式？”">​</a></h3><blockquote><p><strong>回答</strong> : Squid存储的数据是UFS文件格式的。UFS是一种老的，使用比较广泛的Squid存储格式</p></blockquote><h3 id="_10-squid的缓存会存储到哪里" tabindex="-1">10. Squid的缓存会存储到哪里？ <a class="header-anchor" href="#_10-squid的缓存会存储到哪里" aria-label="Permalink to “10. Squid的缓存会存储到哪里？”">​</a></h3><blockquote><p><strong>回答</strong> : Squid存储的缓存是位于 ‘/var/spool/squid’ 的特定目录下。</p></blockquote><p>以上就是全部内容了，很快我还会带着其它有趣的内容回到这里。</p><hr>`,58)),a("p",null,[e[1]||(e[1]=i("via: ",-1)),o(t,{href:"http://www.tecmint.com/squid-interview-questions/"},{default:d(()=>[...e[0]||(e[0]=[i("http://www.tecmint.com/squid-interview-questions/",-1)])]),_:1})]),a("p",null,[e[5]||(e[5]=i("作者：",-1)),o(t,{href:"http://www.tecmint.com/author/avishek/"},{default:d(()=>[...e[2]||(e[2]=[i("Avishek Kumar",-1)])]),_:1}),e[6]||(e[6]=i(" 译者：",-1)),o(t,{href:"https://github.com/ZTinoZ"},{default:d(()=>[...e[3]||(e[3]=[i("ZTinoZ",-1)])]),_:1}),e[7]||(e[7]=i(" 校对：",-1)),o(t,{href:"https://github.com/wxy"},{default:d(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),a("p",null,[e[10]||(e[10]=i("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[8]||(e[8]=[i("LCTT",-1)])]),_:1}),e[11]||(e[11]=i(" 原创翻译，",-1)),o(t,{href:"http://linux.cn/"},{default:d(()=>[...e[9]||(e[9]=[i("Linux中国",-1)])]),_:1}),e[12]||(e[12]=i(" 荣誉推出",-1))])])}const T=n(l,[["render",q]]);export{x as __pageData,T as default};
